begin;
create table if not exists audit.events(id bigint generated always as identity primary key,tenant_id uuid references app.tenants(id),actor_id uuid references authn.users(id),action text not null,entity_type text,entity_id text,request_id text,metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create index if not exists audit_events_tenant_time_idx on audit.events(tenant_id,occurred_at desc);
create table if not exists audit.security_events(id uuid primary key default gen_random_uuid(),tenant_id uuid references app.tenants(id),user_id uuid references authn.users(id),event_type text not null,severity text not null default 'info',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists storage.object_metadata(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,object_key text not null,original_name text not null,content_type text not null,size_bytes bigint not null check(size_bytes>=0),status text not null default 'pending' check(status in('pending','active','deleted','quarantined')),created_by uuid references authn.users(id),created_at timestamptz not null default now(),stored_at timestamptz,deleted_at timestamptz,unique(tenant_id,object_key));
create table if not exists app.notifications(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,user_id uuid references authn.users(id),title text not null,body text not null,kind text not null default 'info',read_at timestamptz,created_at timestamptz not null default now());
create table if not exists app.backup_exports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,object_key text,status text not null default 'requested',checksum_sha256 text,requested_by uuid references authn.users(id),requested_at timestamptz not null default now(),completed_at timestamptz);
create or replace function audit.record_auth_event(p_tenant uuid,p_actor uuid,p_action text,p_metadata jsonb) returns void language sql security definer set search_path=audit,pg_catalog as $$insert into audit.events(tenant_id,actor_id,action,metadata) values(p_tenant,p_actor,p_action,coalesce(p_metadata,'{}'::jsonb))$$;
revoke all on function audit.record_auth_event(uuid,uuid,text,jsonb) from public;
insert into app.schema_migrations(version) values ('0006_audit_storage_security') on conflict do nothing;
commit;
